+document.addEventListener('DOMContentLoaded', () => {
+    // Mobile Menu Toggle
+    const menuToggle = document.querySelector('.menu-toggle');
+    const navLinks = document.querySelector('.nav-links');
+    
+    if (menuToggle && navLinks) {
+        menuToggle.addEventListener('click', () => {
+            const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
+            menuToggle.setAttribute('aria-expanded', !isExpanded);
+            
+            // Simple toggle for mobile visibility
+            // In a real app, we might use a more robust mobile menu
+            if (!isExpanded) {
+                navLinks.style.display = 'flex';
+                navLinks.style.flexDirection = 'column';
+                navLinks.style.position = 'absolute';
+                navLinks.style.top = '100%';
+                navLinks.style.left = '0';
+                navLinks.style.width = '100%';
+                navLinks.style.background = 'white';
+                navLinks.style.padding = '2rem';
+                navLinks.style.borderBottom = '1px solid var(--color-border)';
+            } else {
+                navLinks.style.display = '';
+            }
+        });
+    }
+
+    // Add to Cart Interaction
+    const addToCartButtons = document.querySelectorAll('.add-to-cart');
+    const cartCountElement = document.querySelector('.cart-count');
+    let cartCount = 0;
+
+    addToCartButtons.forEach(button => {
+        button.addEventListener('click', () => {
+            cartCount++;
+            cartCountElement.textContent = cartCount;
+            cartCountElement.setAttribute('aria-label', `Shopping Cart, ${cartCount} items`);
+            
+            // Visual feedback
+            const originalText = button.textContent;
+            button.textContent = 'Added!';
+            button.classList.add('added');
+            
+            // Accessible announcement
+            const announcement = document.createElement('div');
+            announcement.setAttribute('aria-live', 'polite');
+            announcement.classList.add('sr-only');
+            announcement.textContent = `${button.getAttribute('aria-label').replace('Add ', '').replace(' to cart', '')} has been added to your cart.`;
+            document.body.appendChild(announcement);
+            
+            setTimeout(() => {
+                button.textContent = originalText;
+                button.classList.remove('added');
+                document.body.removeChild(announcement);
+            }, 2000);
+        });
+    });
+
+    // Smooth Scroll for anchor links
+    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
+        anchor.addEventListener('click', function (e) {
+            const href = this.getAttribute('href');
+            if (href === '#') return;
+            
+            e.preventDefault();
+            const target = document.querySelector(href);
+            if (target) {
+                target.scrollIntoView({
+                    behavior: 'smooth'
+                });
+                // Set focus to the target for accessibility
+                target.setAttribute('tabindex', '-1');
+                target.focus({ preventScroll: true });
+            }
+        });
+    });
