    margin: 0 auto;
    padding: 0 2rem;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

/* Accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--color-primary);
    color: var(--color-white);
    padding: 8px;
    z-index: 1001;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

button:focus-visible,
a:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 4px;
}

/* Header */
header {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-border);
    padding: 1.5rem 0;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.header-content {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo a {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 2px;
    text-decoration: none;
    color: var(--color-primary);
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    text-decoration: none;
    color: var(--color-text);
    font-weight: 500;
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--color-accent);
}

.header-actions {
    display: flex;
    gap: 1.5rem;
}

.icon-button {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--color-primary);
    display: flex;
    align-items: center;
    position: relative;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background: var(--color-accent);
    color: var(--color-white);
    font-size: 0.75rem;
    padding: 2px 6px;
    border-radius: 50%;
}

.menu-icon {
    display: block;
    width: 24px;
    height: 2px;
    background: var(--color-primary);
    position: relative;
    transition: var(--transition);
}

.menu-icon::before,
.menu-icon::after {
    content: '';
    position: absolute;
    width: 24px;
    height: 2px;
    background: var(--color-primary);
    transition: var(--transition);
}

.menu-icon::before { top: -8px; }
.menu-icon::after { bottom: -8px; }

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

/* Hero */
.hero {
    background-color: var(--color-secondary);
    padding: 8rem 0;
    text-align: center;
}

.hero-text h1 {
    font-size: 3.5rem;
    margin-bottom: 1.5rem;
    font-weight: 300;
}

.hero-text p {
    font-size: 1.25rem;
    color: var(--color-text-muted);
    margin-bottom: 2.5rem;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

/* Buttons */
.button {
    display: inline-block;
    padding: 1rem 2rem;
    text-decoration: none;
    font-weight: 600;
    border: none;
    cursor: pointer;
    transition: var(--transition);
    text-align: center;
}

.button.primary {
    background: var(--color-primary);
    color: var(--color-white);
}

.button.primary:hover {
    background: #333;
}

.button.secondary {
    background: var(--color-secondary);
    color: var(--color-primary);
    border: 1px solid var(--color-primary);
}

.button.secondary:hover {
    background: var(--color-primary);
    color: var(--color-white);
}

.button.inverted {
    background: var(--color-white);
    color: var(--color-primary);
}

.button.ghost {
    background: transparent;
    border-bottom: 2px solid var(--color-primary);
    padding: 0.5rem 0;
}

/* Sections */
.section {
    padding: 6rem 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 3rem;
}

.section-header h2 {
    font-size: 2rem;
    font-weight: 400;
}

.view-all {
    color: var(--color-text-muted);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: var(--transition);
}

.view-all:hover {
    border-bottom-color: var(--color-text-muted);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 2.5rem;
}

.product-card {
    transition: var(--transition);
}

.product-image {
    background: var(--color-secondary);
    overflow: hidden;
    margin-bottom: 1rem;
    aspect-ratio: 4/5;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1.125rem;
    margin-bottom: 0.5rem;
}

.price {
    color: var(--color-text-muted);
    margin-bottom: 1rem;
}

/* Deals */
.deals-banner {
    background: var(--color-primary);
    color: var(--color-white);
    padding: 5rem;
    text-align: center;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deals-content p {
    margin-bottom: 2rem;
    font-size: 1.1rem;
    opacity: 0.9;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.editorial-content p {
    margin-bottom: 2rem;
    font-size: 1.1rem;
    color: var(--color-text-muted);
}

/* Footer */
footer {
    background: var(--color-secondary);
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--color-border);
}

.footer-content {
    display: grid;
    grid-template-columns: 1.5fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.footer-links {
    display: flex;
    justify-content: space-between;
}

.footer-column h3 {
    font-size: 1rem;
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-column ul {
    list-style: none;
}

.footer-column li {
    margin-bottom: 0.75rem;
}

.footer-column a {
    text-decoration: none;
    color: var(--color-text-muted);
    transition: var(--transition);
}

.footer-column a:hover {
    color: var(--color-primary);
}

.footer-bottom {
    border-top: 1px solid var(--color-border);
    padding-top: 2rem;
    text-align: center;
    color: var(--color-text-muted);
    font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .menu-toggle {
        display: block;
    }

    .hero-text h1 {
        font-size: 2.5rem;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .deals-banner {
        padding: 3rem 1.5rem;
    }
}

/* High Contrast Mode Adjustments */
@media (forced-colors: active) {
    .button {
        border: 1px solid ButtonText;
    }
    .cart-count {
        outline: 1px solid CanvasText;
    }
}
