    border-bottom-color: var(--color-text-muted);
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
    gap: 2.5rem;
}

.product-card {
    transition: var(--transition);
}

.product-image {
    background: var(--color-secondary);
    overflow: hidden;
    margin-bottom: 1rem;
    aspect-ratio: 4/5;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1.125rem;
    margin-bottom: 0.5rem;
}

.price {
    color: var(--color-text-muted);
    margin-bottom: 1rem;
}

/* Deals */
.deals-banner {
    background: var(--color-primary);
    color: var(--color-white);
    padding: 5rem;
    text-align: center;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deals-content p {
    margin-bottom: 2rem;
    font-size: 1.1rem;
    opacity: 0.9;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

.editorial-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.editorial-content p {
    margin-bottom: 2rem;
    font-size: 1.1rem;
    color: var(--color-text-muted);
}

/* Footer */
footer {
    background: var(--color-secondary);
    padding: 5rem 0 2rem;
    border-top: 1px solid var(--color-border);
}

.footer-content {
    display: grid;
    grid-template-columns: 1.5fr 1fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-brand .logo {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 1rem;
}

.footer-links {
    display: flex;
    justify-content: space-between;
}

.footer-column h3 {
    font-size: 1rem;
    margin-bottom: 1.5rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-column ul {
    list-style: none;
}

.footer-column li {
    margin-bottom: 0.75rem;
}

.footer-column a {
    text-decoration: none;
    color: var(--color-text-muted);
    transition: var(--transition);
}

.footer-column a:hover {
    color: var(--color-primary);
}

.footer-bottom {
    border-top: 1px solid var(--color-border);
    padding-top: 2rem;
    text-align: center;
    color: var(--color-text-muted);
    font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 768px) {
    .nav-links {
        display: none;
    }

    .menu-toggle {
        display: block;
    }

    .hero-text h1 {
        font-size: 2.5rem;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .footer-content {
        grid-template-columns: 1fr;
        gap: 2rem;
    }

    .deals-banner {
        padding: 3rem 1.5rem;
    }
}

/* High Contrast Mode Adjustments */
@media (forced-colors: active) {
    .button {
        border: 1px solid ButtonText;
    }
    .cart-count {
        outline: 1px solid CanvasText;
    }
}
